content.value:
{
  "brand_name": "AI Product Builder (문제 해결가)",
  "core_value": "End-to-End Product Thinking",
  "definition": "단순히 AI 모델을 학습시키는 개발자에 그치지 않고, 문제 정의부터 기술적 해결, 서비스 구현 및 배포까지 전 과정을 책임지며 실제 사용자의 문제를 해결하는 빌더",
  "key_pillars": [
    {
      "title": "문제 중심 사고",
      "description": "기술의 화려함보다 사용자의 불편함과 문제의 본질에 집중"
    },
    {
      "title": "풀스택 실행력",
      "description": "기획, 데이터 파이프라인, 모델링, 서비스 배포까지 이어지는 전 과정 수행"
    },
    {
      "title": "비즈니스 가치 창출",
      "description": "기술을 도구로 활용해 실제 사업화가 가능한 결과물을 도출"
    }
  ],
  "brand_message": "기술로 문제를 종결하고, 제품으로 가치를 증명합니다."
}

{
  "brand_name": "AI Product Troubleshooter (AI 트러블슈터)",
  "tagline": "정확도 99%를 매출 99%로 만드는 기술 융합 빌더",
  "mission": "기술적 병목을 돌파하여 실험실의 AI를 시장의 프로덕트로 완성한다.",
  "core_values": [
    {
      "value": "집요한 원인 규명 (Deep Persistence)",
      "description": "수치적 오류 뒤에 숨은 진짜 원인을 끝까지 파고들어 해결책을 제시합니다."
    },
    {
      "value": "현장 밀착형 실행 (Field-Ready Execution)",
      "description": "기획부터 배포까지, 이론을 넘어 실제 작동하는 결과물을 빠르게 구현합니다."
    },
    {
      "value": "비즈니스 가치 연결 (Value Integration)",
      "description": "AI 기술을 목적이 아닌 비즈니스 가치를 창출하는 수단으로 최적화합니다."
    }
  ],
  "key_message": "왜 안 되는지 아는 사람, 어떻게 만들어야 할지 아는 빌더.",
  "positioning_statement": "기술적 한계로 멈춰선 AI 프로젝트를 비즈니스 성과로 전환하는 '완결형 AI 시스템 아키텍트'"
}

{
  "brand_name": "AI Product Troubleshooter (AI 트러블슈터)",
  "tagline": "정확도 99%를 매출 99%로 만드는 기술 융합 빌더",
  "mission": "기술적 병목을 돌파하여 실험실의 AI를 시장의 프로덕트로 완성한다.",
  "core_values": [
    {
      "value": "집요한 트러블슈팅 (Deep Troubleshooting)",
      "description": "IoU 0의 기술적 한계에서도 끝까지 원인을 규명하여 작동하는 코드로 증명합니다."
    },
    {
      "value": "현장 중심의 실행력 (Field-Ready Execution)",
      "description": "이론을 넘어 사용자가 즉시 사용할 수 있는 형태의 프로덕트로 빠르게 구현합니다."
    }
  ],
  "positioning": "기술적 한계를 비즈니스 가치로 전환하는 AI 상용화 전문 해결사"
}

